# Supply-chain dependency graph + CVE reachability map.
#
# From a CycloneDX JSON SBOM (generated by trivy) we render a dependency graph
# and identify each component's known CVEs (from osv-scanner results). This is
# the "which vulnerable packages am I actually pulling in / reachable?" view —
# the cutting-edge supply-chain picture on top of SCA.
import json
import logging
from pathlib import Path
from typing import Any

logger = logging.getLogger("h4k.sbom")

REACHABLE_REL_BOM = "https://cyclonedx.org/schema/bom-1.4.schema.json"


def parse_sbom(sbom_path_or_data: str | Path) -> list[dict[str, Any]]:
    """Parse a CycloneDX JSON doc -> list of component dicts.

    Returns [{bom-ref, type, name, version, purl, licenses}] or [] on error.
    """
    if isinstance(sbom_path_or_data, (str, Path)) and Path(sbom_path_or_data).exists():
        data = json.loads(Path(sbom_path_or_data).read_text(encoding="utf-8"))
    elif isinstance(sbom_path_or_data, str):
        try:
            data = json.loads(sbom_path_or_data)
        except json.JSONDecodeError:
            return []
    else:
        data = sbom_path_or_data

    comps: list[dict[str, Any]] = []
    for c in (data or {}).get("components", []) or []:
        licenses = []
        for lic in c.get("licenses", []) or []:
            lic_obj = lic.get("license", {}) or {}
            name = lic_obj.get("name") or lic_obj.get("id")
            if name:
                licenses.append(name)
        comps.append(
            {
                "bom_ref": c.get("bom-ref") or str(c.get("name", "")),
                "type": c.get("type", ""),
                "name": c.get("name", ""),
                "version": c.get("version", ""),
                "purl": c.get("purl", ""),
                "licenses": licenses,
            }
        )
    return comps


def build_graph(sbom_path_or_data: str | Path) -> dict[str, Any]:
    """Return {nodes, edges} adjacency from the SBOM's dependencies section."""
    if isinstance(sbom_path_or_data, (str, Path)) and Path(sbom_path_or_data).exists():
        data = json.loads(Path(sbom_path_or_data).read_text(encoding="utf-8"))
    else:
        data = (
            json.loads(sbom_path_or_data)
            if isinstance(sbom_path_or_data, str)
            else sbom_path_or_data
        )

    # Components indexed by bom-ref (kept in case callers want a lookup).
    comps = parse_sbom(data)

    nodes = [
        {
            "id": c["bom_ref"],
            "label": f"{c['name']}@{c['version']}",
            "type": c["type"],
            "purl": c["purl"],
        }
        for c in comps
    ]

    edges: list[dict[str, str]] = []
    seen: set[str] = set()
    for dep in (data or {}).get("dependencies", []) or []:
        parent = dep.get("ref", "")
        for child in dep.get("dependsOn", []) or []:
            key = f"{parent}>>{child}"
            if key in seen:
                continue
            seen.add(key)
            edges.append({"from": parent, "to": child})

    return {"nodes": nodes, "edges": edges}


def annotate_cves(
    graph: dict[str, Any], cve_map: dict[str, list[str]]
) -> dict[str, Any]:
    """Attach known CVEs to graph nodes by package name (case/fuzzy match).

    cve_map: {package_name: [cve...]} from osv-scanner.
    """
    for node in graph.get("nodes", []):
        label = node.get("label", "")
        name = label.split("@")[0]
        node["cves"] = cve_map.get(name, [])
    # reachability: count of CVEs on the whole graph
    all_cves: list[str] = []
    for n in graph.get("nodes", []):
        all_cves.extend(n.get("cves", []))
    graph["cve_total"] = len(set(all_cves))
    return graph


def build_supply_chain_map(
    sbom_path: str | Path, cve_map: dict[str, list[str]]
) -> dict[str, Any]:
    """Build the full {graph, component CVE list, summary} map."""
    comps = parse_sbom(sbom_path)
    graph = build_graph(sbom_path)
    graph = annotate_cves(graph, cve_map)
    return {
        "components": comps,
        "graph": graph,
        "summary": {
            "components": len(comps),
            "edges": len(graph.get("edges", [])),
            "cves": graph.get("cve_total", 0),
        },
    }
